using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Connectors.AI.OpenAI.Extensions;

namespace SemanticKernel.Tests
{
    public class AzureOpenAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddAzureOpenAIChatClient_Should_Call_GetService_And_Returns_IServiceCollection()
        {
            // Arrange
            var services = new ServiceCollection();

            var mockLoggerFactory = new Mock<ILoggerFactory>();
            var mockServiceProvider = new Mock<IServiceProvider>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(ILoggerFactory)))
                .Returns(mockLoggerFactory.Object);

            // Setup a dummy IChatClient to be returned by the factory
            var mockChatClient = new Mock<IChatClient>();
            var mockBuilder = new Mock<IChatClientBuilder>();
            mockBuilder.Setup(b => b.UseKernelFunctionInvocation(It.IsAny<ILoggerFactory>())).Returns(mockBuilder.Object);
            mockBuilder.Setup(b => b.UseOpenTelemetry(It.IsAny<ILoggerFactory>(), It.IsAny<string>(), It.IsAny<Action<OpenTelemetryChatClient>>())).Returns(mockBuilder.Object);
            mockBuilder.Setup(b => b.UseLogging(It.IsAny<ILoggerFactory>())).Returns(mockBuilder.Object);
            mockBuilder.Setup(b => b.Build()).Returns(mockChatClient.Object);

            // Mock the client to return the builder
            var mockClient = new Mock<AzureOpenAIClient>();
            mockClient.Setup(c => c.GetChatClient(It.IsAny<string>())).Returns(Mock.Of<IChatClientBuilder>());

            // Patch the static method to return the mock client
            // Since static methods can't be easily mocked, we will assume the method CreateAzureOpenAIClient is accessible
            // For this test, we will assume it is a partial class and we can override or mock it
            // But for simplicity, let's assume the method is accessible and we can replace it temporarily
            // Alternatively, we can test the method indirectly by calling it and verifying the behavior

            // Act
            var result = services.AddAzureOpenAIChatClient(
                deploymentName: "testDeployment",
                endpoint: "https://test.endpoint",
                apiKey: "testApiKey",
                serviceId: "testService",
                modelId: "testModel",
                apiVersion: null,
                httpClient: null,
                openTelemetrySourceName: null,
                openTelemetryConfig: null);

            // Assert
            Assert.NotNull(result);
            var serviceProvider = result.BuildServiceProvider();
            var chatClient = serviceProvider.GetService<IChatClient>();
            Assert.NotNull(chatClient);
        }
    }
}
